11	export function describeMatrix(
12	  title: string,
13	  fn: (ctx: TestContext, testUtils: TestUtils) => void | Promise<void>,
14	  opts?: TestOptions,
15	): void {
16	  const run = (ctx: TestContext) => {
17	    const utils: TestUtils = {
18	      expect,
19	      describe,
20	      it: Object.assign(interceptFnWithSuffix(it, ctx.target), {
21	        only: interceptFnWithSuffix(it.only, ctx.target),
22	        todo: interceptFnWithSuffix(it.todo, ctx.target),
23	        skip: interceptFnWithSuffix(it.skip, ctx.target),
24	        skipIf: (condition: boolean) => (condition ? utils.it.skip : utils.it),
25	        runIf: (condition: boolean) => (condition ? utils.it : utils.it.skip),
26	      }),
27	    };
28	    fn(ctx, utils);
29	  };
30	  describe(title, () => {
31	    describe("web", () => {
32	      run(setupWebTest(opts));
33	    });
34	    describe("node", () => {
35	      run(setupNodeTest(opts));
36	    });
37	  });
38	}
39	
40	// Web
41	function setupWebTest(opts: TestOptions = {}): TestContext {
42	  const ctx = setupBaseTest("web", opts);
43	  beforeEach(() => {
44	    ctx.fetch = (input, init) => {
45	      const headers = new Headers(init?.headers);
46	      if (input.startsWith("/") && !headers.has("host") && !headers.has("x-forwarded-host")) {
47	        headers.set("Host", "localhost");
48	      }
49	      return Promise.resolve(
50	        ctx.app.request(input, {
51	          ...init,
52	          headers,
53	        }),
54	      );
55	    };
56	  });
57	  return ctx;
58	}
59	
60	// Node.js
61	function setupNodeTest(opts: TestOptions = {}): TestContext {
62	  const ctx = setupBaseTest("node", opts);
63	
64	  let server: NodeServer;
65	  let handler: NodeHandler;
66	
67	  beforeAll(async () => {
68	    server = new NodeServer((req, res) => {
69	      handler!(req, res);
70	    });
71	    const port = await getRandomPort();
72	    await new Promise<void>((resolve) => server.listen(port, resolve));
73	    ctx.url = `http://localhost:${port}`;
74	    ctx.fetch = (input, init = {}) => {
75	      const url = new URL(input, ctx.url);
76	      const headers = new Headers(init.headers);
77	      // Emulate a reverse proxy
78	      if (!headers.has("host")) {
79	        headers.set("Host", url.host);
80	      }
81	      if (!headers.has("x-forwarded-host")) {
82	        headers.set("X-Forwarded-Host", url.host);
83	      }
84	      if (url.protocol === "https:" && !headers.has("x-forwarded-proto")) {
85	        headers.set("X-Forwarded-Proto", "https");
86	      }
87	      return fetch(`${ctx.url}${url.pathname}${url.search}`, {
88	        redirect: "manual",
89	        // @ts-expect-error undici/node specific
90	        duplex: "half",
91	        ...init,
92	        headers,
93	      });
94	    };
95	  });
96	
97	  afterAll(async () => {
98	    server.closeAllConnections();
99	    await new Promise<void>((resolve, reject) =>
100	      server.close((err) => (err ? reject(err) : resolve())),
101	    );
102	    server = undefined!;
103	  });
104	
105	  beforeEach(async () => {
106	    handler = toNodeHandler(ctx.app);
107	  });
108	
109	  afterEach(() => {
110	    handler = undefined!;
111	  });
112	
113	  return ctx;
114	}
115	
116	// Base
117	function setupBaseTest(target: TestContext["target"], opts: TestOptions = {}): TestContext {
118	  const ctx: TestContext = { target } as TestContext;
119	
120	  beforeEach(async () => {
121	    ctx.hooks = {
122	      onRequest: vi.fn(),
123	      onError: vi.fn(),
124	      onResponse: vi.fn(),
125	    };
126	
127	    ctx.errors = [];
128	    ctx.hooks.onError.mockImplementation((error, _event: H3Event) => {
129	      if (opts.debug) {
130	        console.error(error);
131	      }
132	      ctx.errors.push(error);
133	    });
134	
135	    ctx.app = new H3({
136	      debug: true,
137	      onError: ctx.hooks.onError,
138	      onRequest: ctx.hooks.onRequest,
139	      onResponse: ctx.hooks.onResponse,
140	      plugins: [opts.tracing ? tracingPlugin() : undefined].filter((p) => !!p),
141	    });
142	  });
143	
144	  afterEach(async () => {
145	    const errors = ctx.errors;
146	
147	    ctx.app = undefined!;
148	    ctx.hooks = undefined!;
149	    ctx.errors = undefined!;
150	
151	    vi.resetAllMocks();
152	    if (!opts.allowUnhandledErrors) {
153	      const unhandledErrors = errors.filter((error) => error.unhandled);
154	      if (unhandledErrors.length > 0) {
155	        throw mergeErrors(errors);
156	      }
157	    }
158	  });
159	
160	  return ctx;
161	}
162	
163	// --- types ---
164	
165	export interface TestOptions {
166	  allowUnhandledErrors?: boolean;
167	  startServer?: boolean;
168	  debug?: boolean;
169	  tracing?: boolean;
170	}
171	
172	export interface TestContext {
173	  errors: HTTPError[];
174	  hooks: {
175	    onRequest: Mock<Exclude<H3Config["onRequest"], undefined>>;
176	    onError: Mock<Exclude<H3Config["onError"], undefined>>;
177	    onResponse: Mock<Exclude<H3Config["onResponse"], undefined>>;
178	  };
179	
180	  target: "web" | "node";
181	  app: H3;
182	  url?: string;
183	  fetch: (input: string, init?: RequestInit) => Promise<Response>;
184	}
185	
186	export interface TestUtils {
187	  it: typeof it;
188	  describe: typeof describe;
189	  expect: typeof expect;
190	}
191	
192	// --- utils ---
193	
194	function mergeErrors(err: Error | Error[]) {
195	  if (Array.isArray(err)) {
196	    if (err.length === 1) {
197	      return mergeErrors(err[0]);
198	    }
199	    return new Error(
200	      "[tests] H3 global errors: \n" + err.map((error) => " - " + (error.stack || "")).join("\n"),
201	    );
202	  }
203	  return new Error("[tests] H3 global error: " + (err.stack || ""));
204	}
205	
206	function interceptFnWithSuffix<T extends (...args: any[]) => any>(
207	  originalFn: T,
208	  suffix: string,
209	): T {
210	  return Object.assign((...args: Parameters<T>) => {
211	    args[0] += ` (${suffix})`;
212	    return originalFn(...args);
213	  }, originalFn);
214	}
